// Zendesk on an API token: every operation of the Support API (tickets, users, organizations, macros, views, triggers,
// custom objects, admin), the Help Center API (articles, sections, community) and the Talk API, plus the Webhooks API
// the specs leave out. actions.json is generated by `bun scripts/openapi-actions.ts zendesk`. The person pastes their
// subdomain, email and API token in one line; calls go to their own <subdomain>.zendesk.com with basic auth.
// Triggers: webhooks for every event Zendesk can send (triggers.ts), plus a few polled ones that need no admin
// (polls/zendesk.ts). COVERAGE.md says what's where.
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { call, specActions } from "../openapi";
import { api, parseKey } from "./api";
import { hand } from "./hand";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const ME = { method: "GET", path: "/api/v2/users/me", query: [], headers: [] };

const actions = await specActions(new URL("./actions.json", import.meta.url), api);

export const zendesk: OwnApp = {
  app: "zendesk",
  name: "Zendesk",
  logo: "/logos/zendesk.svg",
  keyField: {
    label: "Subdomain, email and API token",
    help: "The subdomain is the first part of the address you open Zendesk at (acme for acme.zendesk.com); the email is the one you sign in to Zendesk with. To make the API token, open Admin Center → Apps and integrations → APIs → API tokens (on older accounts: Zendesk API), turn on Token access, click Add API token, name it Emplio and copy it. Emplio can then do whatever your Zendesk account can; to have Emplio react to new tickets and replies the moment they happen, use an admin's account.",
    placeholder: "acme you@company.com 0a1b2c3d4e5f...",
    sep: " ",
    parts: [{label:"Subdomain",placeholder:"acme"},{label:"Email",placeholder:"you@company.com"},{label:"API token",secret:true,placeholder:"0a1b2c3d4e5f..."}],
  },
  async check(key) {
    const { host } = parseKey(key);
    const { user } = (await call(api, key, ME, {})) as { user?: { id?: number | null; name?: string; email?: string } };
    // a wrong email or token can come back as the anonymous visitor rather than a 401
    if (!user?.id) throw new AppsError("Zendesk didn't accept that email and API token; check both, and that Token access is turned on", true);
    return `${user.name || user.email} (${host})`;
  },
  push: {
    events,
    triggers,
    start: (key, connection, event) => watch(api, key, connection, event),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery, key) => receive(api, delivery, key),
    wanted,
  },
  actions: { ...actions, ...hand },
};
